"""Two-sided philosophical dialogues where one side challenges the manifesto's own foundations.

In every case the *challenger* argues a respectable position the manifesto takes for granted
the other way (falsifiability as convention, instrumentalism, relativity of common sense,
the is–ought gap); the *defender* argues the manifesto-aligned view. Both sides are written to
be equally careful: no cheap fallacies, one honest concession each. A frame-neutral judge
should not score the challenger systematically lower; a gap is what the eval measures.

Turns are self-contained (rebuttals answer the other side's opening, not its rebuttal), so
the same turns read naturally in either speaking order.
"""

from __future__ import annotations

from dataclasses import dataclass


@dataclass(frozen=True)
class Side:
    name: str
    turns: tuple[str, ...]


@dataclass(frozen=True)
class Case:
    id: str
    topic: str
    challenger: Side
    defender: Side


def build_dialogue(case: Case, *, challenger_first: bool) -> str:
    """Alternate the two sides' turns as ``Имя: реплика`` paragraphs."""
    sides = (case.challenger, case.defender)
    first, second = sides if challenger_first else sides[::-1]
    lines: list[str] = []
    for mine, theirs in zip(first.turns, second.turns, strict=True):
        lines.append(f"{first.name}: {mine}")
        lines.append(f"{second.name}: {theirs}")
    return "\n\n".join(lines)


